import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"数据库","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/数据库.md","filePath":"专业基础/数据库.md","lastUpdated":1792430298000}'),d={name:"专业基础/数据库.md"};function o(i,t,h,s,n,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h1><blockquote><p>数据是安全攻防的核心资产。校内对应「数据库原理及安全」（第 4 学期，含课程设计），数据库安全与隐私保护是重要分支。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>SQL 注入长期位居 Web 漏洞之首，不懂 SQL 就无法理解注入原理；</li><li>数据泄露、隐私保护、合规审计都围绕数据库展开；</li><li>校内「数据库原理及安全」将数据库与安全机制合二为一（见 <a href="./../安全方向/数据库与隐私保护.html">数据库安全与隐私保护</a>）。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>关系模型与 SQL</li><li>索引与事务（ACID、隔离级别）</li><li>数据库设计（ER 模型、范式）</li><li>安全相关：权限管理、SQL 注入原理、数据加密存储、审计日志</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>校内教材（《数据库原理及应用》）</td><td>教材</td><td>以课程为主线</td></tr><tr><td>王道考研《数据库系统概论》</td><td>教辅/视频</td><td>考点梳理</td></tr><tr><td>CMU 15-445: Database Systems</td><td>公开课</td><td>顶级数据库实现课程（<a href="https://15445.courses.cs.cmu.edu/" target="_blank" rel="noreferrer">15445.courses.cs.cmu.edu</a>）</td></tr><tr><td>SQLBolt（<a href="https://sqlbolt.com/" target="_blank" rel="noreferrer">sqlbolt.com</a>）</td><td>交互</td><td>SQL 快速练手</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>先熟练掌握 SQL（增删改查、联表、子查询），这是 Web 安全的入场券；</li><li>学完权限模型后，尝试在自建靶场中复现一次 SQL 注入（仅限授权环境）；</li><li>课程设计认真做，理解「安全」如何贯穿数据生命周期。</li></ul>',10)])])}const b=a(d,[["render",o]]);export{_ as __pageData,b as default};
